import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Menambah watermark hanya butuh beberapa menit, dan watermark melindungi karya Anda ke mana pun gambar pergi. Anda tidak butuh perangkat lunak desain atau akun, dan seluruh pekerjaan berjalan di browser.</p>\n\n<p>Panduan cara ini memandu prosesnya langkah demi langkah. Panduan ini membahas watermark teks dan logo, penempatan, opacity, ukuran, dan pola berulang yang melindungi bukti foto klien.</p>\n\n<p>Di akhir panduan, Anda akan tahu cara menandai satu foto, satu kelompok bukti foto, dan kesalahan yang membuat watermark tidak berguna. Simpan file asli Anda yang tanpa watermark sampai Anda memeriksa hasilnya.</p>\n\n<h2 id=\"before-you-start\">Sebelum Memulai: Yang Anda Butuhkan</h2>\n\n<p>Anda butuh file gambar dan, jika ingin watermark logo, file logo juga. Logo PNG transparan bekerja paling baik, karena area kosongnya membiarkan foto terlihat.</p>\n\n<p>Tentukan dulu apa yang harus dikatakan watermark sebelum membuka tool. Nama, website, atau frasa pendek sudah cukup, dan teks yang lebih pendek lebih mudah dibaca pada ukuran kecil.</p>\n\n<p>Pikirkan juga tujuan Anda. Bukti foto butuh tanda yang kuat dan sulit dihapus, sedangkan gambar jadi untuk media sosial hanya butuh merek ringan di sudut.</p>\n\n<p>Buka <a href=\"/id/tambah-watermark-gambar/\">Tool Watermark Gambar</a> di browser Anda. Semuanya berjalan lokal, sehingga foto dan logo Anda tidak pernah diunggah ke server.</p>\n\n<h2 id=\"step-by-step\">Menambah Watermark dalam Enam Langkah</h2>\n\n<p>Prosesnya sama untuk watermark teks dan watermark logo. Unggah foto, atur tanda, tempatkan, periksa pratinjau, lalu unduh hasilnya.</p>\n\n<p>Luangkan waktu pada penempatan dan opacity. Dua pengaturan itu menentukan apakah watermark melindungi gambar atau hanya menghiasinya.</p>\n\n<ol>\n<li>Unggah foto Anda dengan menyeretnya ke area unggah, memilihnya dari perangkat, atau menempelnya dengan Ctrl+V.</li>\n<li>Ketik teks watermark Anda, atau unggah logo PNG transparan Anda memakai opsi logo.</li>\n<li>Pilih posisi memakai preset jangkar, atau seret watermark ke tempat khusus yang tepat.</li>\n<li>Atur opacity, ukuran, dan sudut rotasi, lalu nyalakan pola berulang untuk bukti foto klien.</li>\n<li>Pratinjau hasilnya pada bagian gambar yang terang dan gelap untuk memastikan tanda tetap terbaca.</li>\n<li>Pilih format dan kualitas ekspor, lalu klik Unduh untuk menyimpan gambar ber-watermark.</li>\n</ol>\n\n<p>Buka file unduhan sekali sebelum membagikannya. Pastikan watermark terbaca jelas dan foto di bawahnya tetap terlihat bagus.</p>\n\n<h2 id=\"choosing-text-or-logo\">Memilih antara Watermark Teks dan Logo</h2>\n\n<p>Watermark teks adalah pilihan tercepat. Ketik nama atau website Anda, dan tool menampilkannya di atas foto dalam hitungan detik, tanpa file tambahan.</p>\n\n<p>Watermark logo terlihat lebih profesional, terutama untuk fotografer dan studio. Unggah PNG transparan dari merek Anda, dan logo tampil di atas foto persis seperti yang dirancang.</p>\n\n<p>Teks lebih baik saat tujuannya adalah pemberitahuan hak cipta yang jelas. Nama dan tahun tidak menyisakan keraguan tentang kepemilikan, sedangkan logo saja mungkin tidak dikenali oleh orang asing.</p>\n\n<p>Anda bisa memakai keduanya sekaligus. Logo kecil di sudut dengan website Anda tertulis di bawahnya memberi branding dan atribusi dalam satu tanda.</p>\n\n<h2 id=\"typing-watermark-text\">Mengetik Teks Watermark Anda</h2>\n\n<p>Jaga teks tetap pendek. Nama, nama studio, atau alamat website sudah cukup, dan teks pendek tetap terbaca bahkan pada ukuran kecil.</p>\n\n<p>Hindari kalimat panjang dalam watermark. Pemberitahuan hak cipta yang panjang sulit dibaca di atas foto yang ramai, dan menutupi lebih banyak gambar dari yang dibutuhkan.</p>\n\n<p>Gunakan nama asli atau nama bisnis Anda, bukan nama panggilan yang tidak dikenali siapa pun. Watermark dimaksudkan untuk mengidentifikasi Anda, jadi watermark harus menyatakan siapa Anda.</p>\n\n<p>Jika Anda membiarkan kolom teks kosong, tool tidak memiliki apa pun untuk ditampilkan sebagai tanda teks. Ketik teks dulu, lalu sesuaikan ukuran dan posisinya.</p>\n\n<h2 id=\"uploading-a-logo\">Mengunggah Logo Anda sebagai Watermark</h2>\n\n<p>Siapkan logo Anda sebagai PNG transparan sebelum memulai. Transparansi membiarkan foto terlihat melalui area kosong, sehingga hanya logo itu sendiri yang tampil di atas gambar.</p>\n\n<p>Logo JPG memiliki latar putih solid yang tampil sebagai persegi di atas foto Anda. Logo itu terlihat tidak profesional, dan mudah dikenali sebagai kesalahan.</p>\n\n<p>Unggah logo melalui opsi logo di tool. Anda bisa menggantinya nanti tanpa memuat ulang halaman, dan ini berguna saat Anda ingin menguji tanda yang berbeda.</p>\n\n<p>Periksa logo pada ukuran yang akan Anda pakai. Logo detail yang terlihat bagus pada ukuran penuh bisa berubah menjadi buram pada ukuran watermark kecil, jadi sederhanakan bila perlu.</p>\n\n<h2 id=\"choosing-placement\">Memilih Tempat Watermark</h2>\n\n<p>Preset jangkar menempatkan tanda di tempat standar: sudut, tepi, atau tengah. Sudut paling tidak mengganggu, sedangkan tengah paling sulit dihapus.</p>\n\n<p>Seret watermark ke tempat khusus yang tepat saat preset tidak cocok. Anda bisa menempatkan tanda di atas area polos foto, ketika tanda terbaca tanpa menutupi subjek.</p>\n\n<p>Untuk branding, sudut bawah biasanya paling baik. Sudut itu menandai gambar dengan jelas tanpa menutupi subjek, dan penonton berharap menemukan logo di sana.</p>\n\n<p>Untuk perlindungan, tengah atau posisi diagonal lebih baik. Tanda di tengah tidak bisa dipotong tanpa menghancurkan foto itu sendiri.</p>\n\n<h2 id=\"setting-opacity\">Mengatur Opacity</h2>\n\n<p>Opacity mengontrol seberapa kuat watermark terlihat. Pada 100 persen, tanda solid dan menutupi gambar di bawahnya, sedangkan pada 10 persen, tanda adalah bayangan samar yang mudah terlewat.</p>\n\n<p>Untuk bukti foto klien, gunakan 30 sampai 50 persen. Tandanya jelas terbaca, sehingga mencegah penyalahgunaan, tetapi klien masih bisa menilai foto di bawahnya.</p>\n\n<p>Untuk branding pada gambar jadi, 15 sampai 25 persen biasanya cukup. Logo terlihat tanpa mengganggu foto, dan tidak berebut perhatian dengan subjek.</p>\n\n<p>Uji opacity pada bagian gambar yang terang maupun gelap. Tanda yang jelas pada latar gelap bisa hilang pada langit terang, dan sebaliknya juga benar.</p>\n\n<h2 id=\"setting-size\">Mengatur Ukuran Watermark</h2>\n\n<p>Teks watermark berukuran sebagai persentase gambar, bukan sebagai jumlah piksel tetap. Pengaturan yang sama terlihat konsisten pada thumbnail kecil dan foto kamera besar.</p>\n\n<p>Ukuran yang terlihat tepat pada foto besar bisa tidak terlihat pada foto kecil jika diatur dalam piksel. Ukuran persentase menghindari masalah itu sepenuhnya.</p>\n\n<p>Periksa ukurannya pada dimensi sebenarnya yang akan Anda bagikan. Tanda yang terlihat halus pada ukuran penuh bisa mendominasi pratinjau kecil, dan tanda yang berukuran untuk thumbnail bisa hilang pada cetakan besar.</p>\n\n<p>Saat Anda memberi watermark pada kelompok foto berukuran berbeda, ukuran persentase menjaga hasil tetap konsisten di semuanya tanpa kerja tambahan dari Anda.</p>\n\n<h2 id=\"setting-rotation\">Mengatur Sudut Rotasi</h2>\n\n<p>Sudut kecil, biasanya sekitar 30 sampai 45 derajat, membuat watermark lebih sulit dihapus dan kurang seperti keterangan. Tanda diagonal melintasi lebih banyak gambar daripada tanda horizontal.</p>\n\n<p>Untuk bukti foto, tanda diagonal adalah pilihan yang lebih kuat. Tanda itu melewati tengah dan tepi, sehingga tidak ada satu potongan pun yang bisa menghapusnya dengan bersih.</p>\n\n<p>Untuk branding, jaga sudut tetap nol. Logo lurus di sudut terlihat profesional, sedangkan logo miring terlihat seperti kesalahan yang lolos.</p>\n\n<p>Sesuaikan sudut dalam langkah kecil dan perhatikan pratinjau. Beberapa derajat bisa membuat perbedaan antara tanda yang terlihat disengaja dan tanda yang terlihat tidak sengaja.</p>\n\n<h2 id=\"tiled-repeat-mode\">Menggunakan Pola Berulang</h2>\n\n<p>Satu watermark di sudut mudah dihapus, karena siapa pun bisa memotong sudut atau mengecat satu tanda kecil. Pola berulang memecahkan masalah itu.</p>\n\n<p>Mode berulang menempatkan watermark berulang kali di seluruh gambar dalam grid, sehingga tidak ada potongan yang bisa menghapus semuanya. Mode ini adalah standar untuk bukti foto klien.</p>\n\n<p>Saat mode berulang aktif, preset jangkar tersembunyi, karena pola menutupi seluruh bingkai sesuai desainnya. Anda mengontrol jarak dan sudutnya sebagai gantinya.</p>\n\n<p>Gunakan opacity yang lebih rendah untuk tanda berulang daripada tanda tunggal. Pola berulang pada opacity tinggi mengalahkan foto, sedangkan pengulangan ringan melindunginya tanpa menyembunyikannya.</p>\n\n<h2 id=\"preview-and-compare\">Mempratinjau Sebelum Mengunduh</h2>\n\n<p>Selalu pratinjau sebelum mengunduh. Pratinjau menunjukkan persis bagaimana watermark akan terlihat pada file ekspor, termasuk ukuran, opacity, dan posisinya.</p>\n\n<p>Periksa tanda pada bagian foto yang paling ramai. Watermark yang terbaca jelas pada dinding polos bisa hilang di hutan, keramaian, atau kain bermotif.</p>\n\n<p>Periksa juga pada area paling terang dan paling gelap. Tanda putih hilang pada langit terang, dan tanda gelap hilang dalam bayangan, jadi uji kedua ekstrem itu.</p>\n\n<p>Jika tanda tidak terbaca di tempat penting, ubah warnanya, tambahkan garis tepi, atau pindahkan ke area yang lebih polos. Memperbaikinya sekarang lebih cepat daripada mengulang seluruh pekerjaan.</p>\n\n<h2 id=\"choosing-export-format\">Memilih Format Ekspor</h2>\n\n<p>Pilih JPG untuk foto yang Anda rencanakan untuk dibagikan atau dikirim ke klien. Format ini menjaga ukuran file tetap kecil dan berfungsi di mana pun, termasuk formulir lama dan aplikasi pesan.</p>\n\n<p>Pilih PNG saat gambar dasar adalah grafis transparan atau logo. PNG mempertahankan transparansi, sehingga area tembus pandang tetap tembus pandang dalam ekspor.</p>\n\n<p>Pilih WebP saat Anda ingin file kecil dengan kualitas bagus. Format ini cocok untuk gambar web, meskipun beberapa sistem lama masih menolaknya.</p>\n\n<p>Ingatlah bahwa penggeser kualitas tersembunyi untuk PNG, karena PNG bersifat lossless dan tidak memiliki pengaturan kualitas untuk disesuaikan. Itu perilaku normal, bukan masalah pada tool.</p>\n\n<h2 id=\"watermarking-on-mobile\">Memberi Watermark di Ponsel atau Tablet</h2>\n\n<p>Tool ini berfungsi di layar sentuh, sehingga Anda bisa memberi watermark pada foto di ponsel yang mengambilnya. Unggah dari galeri, ketik teks, lalu seret tanda ke tempatnya dengan jari.</p>\n\n<p>Menempatkan dengan jari kurang presisi daripada dengan mouse, jadi gunakan preset jangkar untuk sudut yang tepat. Preset menempatkan tanda dengan sempurna tanpa menyeret apa pun.</p>\n\n<p>Periksa pratinjau pada ukuran penuh sebelum mengunduh. Tanda yang terlihat bagus di layar ponsel kecil bisa terlalu besar atau terlalu samar saat dilihat di komputer.</p>\n\n<p>File unduhan tersimpan di folder unduhan biasa Anda. Dari sana Anda bisa langsung membagikannya ke klien, email, atau postingan sosial.</p>\n\n<h2 id=\"troubleshooting\">Mengatasi Masalah Watermark Umum</h2>\n\n<p>Jika watermark tidak terlihat, opacity mungkin terlalu rendah atau warnanya cocok dengan latar. Naikkan opacity atau ganti warnanya, lalu periksa pratinjau lagi.</p>\n\n<p>Jika watermark menutupi subjek, pindahkan ke area yang lebih polos atau kecilkan ukurannya. Tanda yang menyembunyikan wajah atau produk menggagalkan tujuan foto.</p>\n\n<p>Jika preset jangkar hilang, periksa apakah mode berulang aktif. Preset tersembunyi dalam mode berulang karena pola menutupi seluruh bingkai, dan preset kembali saat Anda mematikannya.</p>\n\n<p>Jika logo menampilkan kotak putih, file logo adalah JPG, bukan PNG transparan. Ganti dengan PNG transparan dan persegi putih itu akan hilang.</p>\n\n<h2 id=\"quick-tips\">Tips Cepat untuk Watermark yang Lebih Baik</h2>\n\n<p>Beri watermark pada salinan, bukan pada file asli. Setelah tanda diratakan ke dalam ekspor, tanda itu tidak bisa dihapus dari file tersebut, sehingga file asli adalah satu-satunya versi bersih Anda.</p>\n\n<p>Jaga teks tetap pendek dan logo tetap sederhana. Tanda yang mudah dibaca sekilas melindungi lebih baik daripada tanda detail yang berubah menjadi buram.</p>\n\n<p>Uji watermark pada foto yang ramai sebelum menerapkannya ke satu kelompok. Tanda yang berfungsi pada latar polos bisa gagal pada pemandangan yang rumit.</p>\n\n<p>Simpan pengaturan Anda dengan mencatatnya: opacity, ukuran, sudut, dan posisi. Catatan singkat memungkinkan Anda menghasilkan tanda yang sama pada setiap gambar yang Anda terbitkan.</p>\n\n<p>Kerjakan dalam kelompok kecil yang terdiri dari sepuluh sampai dua puluh foto, lalu istirahat sejenak dan periksa hasilnya. Mata yang lelah mudah melewatkan watermark yang terlalu samar atau salah tempat.</p>\n\n<p>Periksa foto pertama dan terakhir dari setiap kelompok dengan saksama. Jika keduanya konsisten, kemungkinan besar seluruh kelompok juga konsisten, dan Anda bisa melanjutkan dengan percaya diri.</p>\n\n<p>Beri nama folder kelompok dengan tanggal dan nama acara, misalnya pernikahan-sinta-2026-bukti. Nama yang jelas mencegah Anda tertukar antara kelompok yang sudah diberi watermark dan yang belum.</p>\n\n<p>Jangan memberi watermark sambil terburu-buru mengejar tenggat. Kesalahan kecil seperti ejaan nama yang salah pada watermark bisa merusak kesan profesional Anda di mata klien.</p>\n\n<p>Simpan catatan pengaturan di dalam folder kelompok itu sendiri, misalnya sebagai file teks kecil. Catatan ini membantu Anda mengulang pengaturan yang sama saat klien meminta tambahan foto dari acara yang sama.</p>\n\n<p>Setelah selesai, kirim tautan pratinjau kepada klien dan minta konfirmasi bahwa watermark terlihat jelas di perangkat mereka. Ponsel dan laptop menampilkan opacity secara berbeda, dan konfirmasi ini menghindari kesalahpahaman.</p>\n\n<p>Periksa juga tanggal dan nama acara pada folder kelompok sebelum mengirimkannya. Folder yang tertukar bisa membuat klien menerima foto acara orang lain, dan kesalahan ini sulit diperbaiki setelah foto dibagikan.</p>\n\n<p>Untuk acara besar seperti pernikahan, mintalah klien memeriksa beberapa foto contoh sebelum Anda mengerjakan seluruh kelompok. Persetujuan awal ini memastikan pengaturan watermark Anda sesuai dengan harapan klien.</p>\n\n<p>Simpan daftar kelompok yang sudah selesai dalam spreadsheet sederhana. Daftar ini membantu Anda melacak pesanan yang sudah dikirim dan yang masih menunggu pembayaran.</p>\n\n<h2 id=\"watermarking-a-batch\">Memberi Watermark pada Satu Kelompok Foto</h2>\n\n<p>Pernikahan atau acara bisa menghasilkan ratusan foto yang semuanya butuh tanda yang sama. Beri watermark satu per satu, dengan pengaturan yang sama di seluruh kelompok.</p>\n\n<p>Tuliskan pengaturan Anda sebelum memulai: teks atau logo, opacity, ukuran, sudut, dan posisi. Catatan singkat menjaga setiap foto dalam kelompok tetap konsisten.</p>\n\n<p>Kerjakan kelompok secara berurutan dan pratinjau setiap foto kesepuluh. Pemeriksaan cepat menangkap pengaturan yang bergeser sebelum memengaruhi puluhan file.</p>\n\n<p>Simpan kelompok ber-watermark di folder terpisah dari file asli. Nama folder yang jelas, misalnya bukti-ber-watermark, mencegah Anda mencampur file bertanda dan file bersih.</p>\n\n<p>Untuk aturan penempatan dan branding, baca <a href=\"/id/blog/tips-watermark-foto-yang-benar/\">Tips Watermark Foto yang Benar: Penempatan, Opacity, dan Branding</a>. Untuk gambaran menyeluruh, lihat <a href=\"/id/blog/panduan-watermark-gambar/\">Panduan Lengkap Watermark Gambar</a>, dan untuk menambah keterangan sebagai pengganti tanda, coba <a href=\"/id/tambah-teks-ke-gambar/\">Tool Tambah Teks ke Gambar</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Bagaimana cara menambah watermark pada foto di ponsel?","answer":"Buka Tool Watermark Gambar di browser ponsel, unggah foto dari galeri, lalu ketik teks Anda atau unggah logo PNG transparan. Gunakan preset jangkar untuk penempatan yang tepat, atur opacity, pratinjau hasilnya, lalu unduh file."},{"question":"Posisi watermark apa yang terbaik untuk foto?","answer":"Sudut bawah paling baik untuk branding, karena menandai gambar tanpa menutupi subjek. Tengah atau posisi diagonal paling baik untuk perlindungan, karena tidak bisa dipotong. Pilih berdasarkan apakah Anda menginginkan branding atau perlindungan."},{"question":"Bisakah saya memberi watermark pada banyak foto sekaligus?","answer":"Tool menangani satu foto setiap kalinya, jadi beri watermark pada setiap gambar secara terpisah dan jaga pengaturannya tetap konsisten. Catat opacity, ukuran, sudut, dan posisi Anda agar setiap foto dalam kelompok membawa tanda yang sama."},{"question":"Mengapa watermark saya tidak terlihat di sebagian foto?","answer":"Warna tanda mungkin cocok dengan latar di area itu. Teks putih hilang pada langit terang dan teks gelap hilang dalam bayangan. Ubah warnanya, tambahkan garis tepi, atau pindahkan tanda ke area gambar yang lebih polos."},{"question":"Bagaimana cara membuat watermark yang tidak bisa dipotong?","answer":"Gunakan pola berulang, yang menempatkan watermark di seluruh gambar dalam grid. Tidak ada satu potongan pun yang bisa menghapus semuanya. Gabungkan pola berulang dengan sudut diagonal dan opacity sedang untuk perlindungan terkuat."},{"question":"Apakah menambah watermark mengubah ukuran file gambar?","answer":"Hanya sedikit. Watermark menambah sedikit data, tetapi ukuran file sebagian besar tergantung format dan pengaturan kualitas ekspor. Ekspor JPG dengan pengaturan kualitas tinggi tetap mendekati ukuran asli."}];
